--- packages/KNIRVHASHER/internal/config/config.go	
+++ packages/KNIRVHASHER/internal/config/config.go	
@@ -1,152 +1,152 @@
 package config

 import (
 	"os"
 	"path/filepath"
 	"strings"
 )

 type DeviceConfig struct {
 	IP          string
 	Password    string
 	Username    string
 	FramesDir   string // path to training frame JSON files for FlashSearcher
 	CGMinerHost string // CGMiner API host (e.g. 192.168.12.151); empty = disabled
 }

 var (
 	deviceConfig *DeviceConfig
 	configLoaded bool
 )

 func LoadDeviceConfig() (*DeviceConfig, error) {
 	if deviceConfig != nil && configLoaded {
 		return deviceConfig, nil
 	}

 	cfg := &DeviceConfig{}

 	// Try to load from .env file in project root
 	projectRoot := findProjectRoot()
 	envPath := filepath.Join(projectRoot, ".env")

 	data, err := os.ReadFile(envPath)
 	if err == nil {
 		parseEnvFile(string(data), cfg)
 	}

 	// Override with environment variables if set
 	if ip := os.Getenv("DEVICE_IP"); ip != "" {
 		cfg.IP = ip
 	}
 	if password := os.Getenv("DEVICE_PASSWORD"); password != "" {
 		cfg.Password = password
 	}
 	if username := os.Getenv("DEVICE_USERNAME"); username != "" {
 		cfg.Username = username
 	}
 	if framesDir := os.Getenv("FRAMES_DIR"); framesDir != "" {
 		cfg.FramesDir = framesDir
 	}
 	if cgminerHost := os.Getenv("CGMINER_HOST"); cgminerHost != "" {
 		cfg.CGMinerHost = cgminerHost
 	}

 	// Set default FramesDir if still empty
 	if cfg.FramesDir == "" {
 		if appData := os.Getenv("KNIRV_APP_DATA_DIR"); appData != "" {
-			cfg.FramesDir = filepath.Join(appData, "hasher", "data", "frames")
-		} else if err := os.MkdirAll("/var/lib/knirvserver/hasher/data/frames", 0755); err == nil {
-			cfg.FramesDir = "/var/lib/knirvserver/hasher/data/frames"
+			cfg.FramesDir = filepath.Join(appData, "knirvhasher", "data", "frames")
+		} else if err := os.MkdirAll("/var/lib/knirvserver/knirvhasher/data/frames", 0755); err == nil {
+			cfg.FramesDir = "/var/lib/knirvserver/knirvhasher/data/frames"
 		} else if home, err := os.UserHomeDir(); err == nil {
-			cfg.FramesDir = filepath.Join(home, ".local", "share", "knirvserver", "hasher", "data", "frames")
+			cfg.FramesDir = filepath.Join(home, ".local", "share", "knirvserver", "knirvhasher", "data", "frames")
 		}
 	}

 	deviceConfig = cfg
 	configLoaded = true
 	return cfg, nil
 }

 func parseEnvFile(content string, cfg *DeviceConfig) {
 	lines := strings.Split(content, "\n")
 	for _, line := range lines {
 		line = strings.TrimSpace(line)
 		if line == "" || strings.HasPrefix(line, "#") {
 			continue
 		}
 		parts := strings.SplitN(line, "=", 2)
 		if len(parts) != 2 {
 			continue
 		}
 		key := strings.TrimSpace(parts[0])
 		value := strings.TrimSpace(parts[1])

 		switch key {
 		case "DEVICE_IP":
 			cfg.IP = value
 		case "DEVICE_PASSWORD":
 			cfg.Password = value
 		case "DEVICE_USERNAME":
 			cfg.Username = value
 		case "FRAMES_DIR":
 			cfg.FramesDir = value
 		case "CGMINER_HOST":
 			cfg.CGMinerHost = value
 		}
 	}
 }

 func findProjectRoot() string {
 	cwd, _ := os.Getwd()
 	// First check CWD for .env file
 	if _, err := os.Stat(filepath.Join(cwd, ".env")); err == nil {
 		return cwd
 	}
 	// Then walk up looking for go.mod
 	for {
 		if _, err := os.Stat(filepath.Join(cwd, "go.mod")); err == nil {
 			return cwd
 		}
 		parent := filepath.Dir(cwd)
 		if parent == cwd {
 			return cwd
 		}
 		cwd = parent
 	}
 }

 func GetDeviceIP() string {
 	cfg, err := LoadDeviceConfig()
 	if err != nil || cfg.IP == "" {
 		return ""
 	}
 	return cfg.IP
 }

 func GetDevicePassword() string {
 	cfg, err := LoadDeviceConfig()
 	if err != nil || cfg.Password == "" {
 		return ""
 	}
 	return cfg.Password
 }

 func GetDeviceUsername() string {
 	cfg, err := LoadDeviceConfig()
 	if err != nil || cfg.Username == "" {
 		return ""
 	}
 	return cfg.Username
 }

 func MustGetDeviceConfig() DeviceConfig {
 	cfg, err := LoadDeviceConfig()
 	if err != nil {
 		panic("DEVICE_IP and DEVICE_PASSWORD must be set in .env file")
 	}
 	if cfg.IP == "" || cfg.Password == "" {
 		panic("DEVICE_IP and DEVICE_PASSWORD must be set in .env file")
 	}
 	return *cfg
 }

