 func killStaleHasher(binaryPath string) {
 	if binaryPath == "" {
 		return
 	}
 	binaryName := filepath.Base(binaryPath)
 	if cmd := exec.Command("pkill", "-TERM", "-x", binaryName); cmd.Run() == nil {
 		time.Sleep(1 * time.Second)
 	}
 	exec.Command("pkill", "-KILL", "-x", binaryName).Run()
 }

